    // $covered: bitmask of covered spiders
    // $start: index in $cells array from which to start (to avoid permutations)
    // $count: number of cells chosen so far

    $dfs = function($covered, $start, $count) use ($cells, $cell_to_spiders, $all_mask, &$best) {
