            if ($mask & $spider_bit) {
                $new_covered = $covered | $mask;
                $dfs($new_covered, $i + 1, $count + 1);
            }
        }
    };

    $dfs(0, 0, 0);

    // The minimum number of occupied cells is $best
    // The number of empty cells is total - $best
    echo ($total - $best) . "\n";
}

