// Read input
$line = trim(fgets(STDIN));
if ($line === false) return;
$parts = explode(' ', $line);
$n = (int)$parts[0];
$m = (int)$parts[1];

// Total cells
$total = $n * $m;

// If total is 1, answer is 0
if ($total == 1) {
    echo 0;
    return;
}

// We need to find the maximum number of empty cells after one second.
// Each spider starts at a cell (i, j). It can move to one of 5 positions: stay, up, down, left, right (if valid).
// We want to choose a destination for each spider such that the number of cells with at least one spider is minimized.
// Equivalently, maximize the number of cells with zero spiders.

// This is a bipartite matching problem:
// Left side: spiders (one per cell)
// Right side: cells
// Edge from spider at (i,j) to cell (x,y) if spider can move to (x,y) in one step.
// We want to find the maximum matching (assigning spiders to cells such that no two spiders are assigned to the same cell).
// The number of matched spiders = number of occupied cells.
// Max empty cells = total - (size of maximum matching).

// Build adjacency list
// Spiders are indexed by cell index: i * m + j
// Cells are also indexed by cell index: i * m + j

$adj = array();
for ($i = 0; $i < $n; $i++) {
    for ($j = 0; $j < $m; $j++) {
        $spiderIdx = $i * $m + $j;
        $adj[$spiderIdx] = array();
        // Stay
        $adj[$spiderIdx][] = $spiderIdx;
        // Up
        if ($i > 0) {
            $adj[$spiderIdx][] = ($i - 1) * $m + $j;
        }
        // Down
        if ($i < $n - 1) {
            $adj[$spiderIdx][] = ($i + 1) * $m + $j;
        }
        // Left
        if ($j > 0) {
            $adj[$spiderIdx][] = $i * m + ($j - 1);
        }
        // Right
        if ($j < $m - 1) {
            $adj[$spiderIdx][] = $i * m + ($j + 1);
        }
    }
}

// Hopcroft-Karp algorithm for maximum bipartite matching
// Left nodes: 0 to total-1 (spiders)
// Right nodes: 0 to total-1 (cells)

$pairU = array_fill(0, $total, -1); // match for left node
$pairV = array_fill(0, $total, -1); // match for right node

function bfs(&$dist, $adj, $pairU, $pairV, $total) {
    $queue = array();
    for ($u = 0; $u < $total; $u++) {
        if ($pairU[$u] == -1) {
            $dist[$u] = 0;
            $queue[] = $u;
        } else {
            $dist[$u] = -1;
        }
    }
    $found = false;
    while (count($queue) > 0) {
        $u = array_shift($queue);
        foreach ($adj[$u] as $v) {
            $u2 = $pairV[$v];
            if ($u2 != -1 && $dist[$u2] == -1) {
                $dist[$u2] = $dist[$u] + 1;
                $queue[] = $u2;
            }
            if ($u2 == -1) {
                $found = true;
            }
        }
    }
    return $found;
}

function dfs($u, $adj, $pairU, $pairV, $dist, $total) {
    foreach ($adj[$u] as $v) {
        $u2 = $pairV[$v];
        if ($u2 == -1 || ($dist[$u2] == $dist[$u] + 1 && dfs($u2, $adj, $pairU, $pairV, $dist, $total))) {
            $pairU[$u] = $v;
            $pairV[$v] = $u;
            return true;
        }
    }
    $dist[$u] = -1;
    return false;
}

$matching = 0;
while (true) {
    $dist = array_fill(0, $total, -1);
    if (!bfs($dist, $adj, $pairU, $pairV, $total)) break;
    for ($u = 0; $u < $total; $u++) {
        if ($pairU[$u] == -1) {
            if (dfs($u, $adj, $pairU, $pairV, $dist, $total)) {
                $matching++;
            }
        }
    }
}

echo $total - $matching;
