// Build adjacency list
// Spider at (r, c) can go to:
// (r, c) - stay
// (r-1, c) - up
// (r+1, c) - down
// (r, c-1) - left
// (r, c+1) - right
// if within bounds

$adj = array();
for ($r = 0; $r < $n; $r++) {
    for ($c = 0; $c < $m; $c++) {
        $spiderIdx = $r * $m + $c;
        $neighbors = array();
        // stay
        $neighbors[] = $spiderIdx;
        // up
        if ($r > 0) $neighbors[] = ($r - 1) * $m + $c;
        // down
        if ($r < $n - 1) $neighbors[] = ($r + 1) * $m + $c;
        // left
        if ($c > 0) $neighbors[] = $r * $m + ($c - 1);
        // right
        if ($c < $m - 1) $neighbors[] = $r * $m + ($c + 1);
        $adj[$spiderIdx] = $neighbors;
    }
}

// Maximum bipartite matching using DFS (Kuhn's algorithm)
